import{_ as n,o as t,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"HA-YAML","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/ha-yaml.md","filePath":"projects/logic-studio/user-guide/ha-yaml.md","lastUpdated":1794767865000}'),i={name:"projects/logic-studio/user-guide/ha-yaml.md"};function o(u,e,s,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ha-yaml" tabindex="-1">HA-YAML <a class="header-anchor" href="#ha-yaml" aria-label="Permalink to &quot;HA-YAML&quot;">​</a></h1><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Öffne eine kleine HA-Automation als YAML-Entwurf. Wechsle zu <strong>Grafisch</strong>, finde Auslöser und Aktionen und wechsle zurück zu <strong>YAML</strong>. Klicke auf <strong>Prüfen</strong> und exportiere die Datei.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="yaml-eingabe-und-import" tabindex="-1">YAML-Eingabe und Import <a class="header-anchor" href="#yaml-eingabe-und-import" aria-label="Permalink to &quot;YAML-Eingabe und Import&quot;">​</a></h3><p>Öffne eine YAML-Datei oder füge YAML ein. Der JSON-Import unterstützt HA-Automationsdaten und kompatible FLODE-Exporte.</p><h3 id="syntax-und-struktur" tabindex="-1">Syntax und Struktur <a class="header-anchor" href="#syntax-und-struktur" aria-label="Permalink to &quot;Syntax und Struktur&quot;">​</a></h3><p>Farben helfen beim Lesen. Prüfen markiert Syntaxfehler, unbekannte Entitäten, ungültige Aktionsfelder und Fehler in verschachtelten <code>choose</code>-Zweigen an der Zeile.</p><h3 id="entitaten-und-aktionen-einfugen" tabindex="-1">Entitäten und Aktionen einfügen <a class="header-anchor" href="#entitaten-und-aktionen-einfugen" aria-label="Permalink to &quot;Entitäten und Aktionen einfügen&quot;">​</a></h3><p>Setze den Cursor an die gewünschte Stelle. Wähle eine Entität oder HA-Aktion, um ihren Bezeichner dort einzufügen.</p><h3 id="grafisch" tabindex="-1">Grafisch <a class="header-anchor" href="#grafisch" aria-label="Permalink to &quot;Grafisch&quot;">​</a></h3><p>Verschiebe und zoome den Ablauf. <strong>Alles einpassen</strong> zeigt den ganzen Plan. Beschriftete <code>choose</code>-Ausgänge zeigen, welcher Zweig zu welcher Aktion führt.</p><h3 id="yaml-und-json-export" tabindex="-1">YAML- und JSON-Export <a class="header-anchor" href="#yaml-und-json-export" aria-label="Permalink to &quot;YAML- und JSON-Export&quot;">​</a></h3><p>Nutze YAML für HA. Verwende die JSON-Ansicht für den JSON-Export. Ein unveränderter YAML-Entwurf kann inklusive unbekannter Felder und Blueprint-Feldern zurückexportiert werden.</p><h3 id="ha-verknupfung" tabindex="-1">HA-Verknüpfung <a class="header-anchor" href="#ha-verknupfung" aria-label="Permalink to &quot;HA-Verknüpfung&quot;">​</a></h3><p>Wähle optional eine vorhandene Automation oder ein Skript. Du kannst den Status prüfen und die angebotenen Steueraktionen nutzen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn eine Zeile rot markiert ist, prüfe Einrückung und Feldnamen. Die grafische Ansicht dient zur Vorschau. Änderungen nimmst du im YAML vor.</p>',18)])])}const f=n(i,[["render",o]]);export{p as __pageData,f as default};
